package dev.inscribed;
import com.mojang.authlib.GameProfile;
import java.util.*;
import dev.inscribed.altar.*;
import dev.inscribed.ritual.*;
import dev.inscribed.pedestal.*;
import dev.inscribed.registry.InscribedRegistries;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.core.component.DataComponents;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.inventory.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.phys.*;
import net.neoforged.fml.ModList;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("inscribed") @PrefixGameTestTemplate(false)
public final class Hardening06GameTests {
    private static final BlockPos T=new BlockPos(10,2,10),P=T.offset(-2,0,0),S=T.offset(0,0,-3);
    private static ResourceLocation id(String s){return ResourceLocation.parse(s);}
    private static net.minecraft.core.Holder<Enchantment> enchant(GameTestHelper h,String s){return h.getLevel().registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolder(id(s)).orElseThrow();}
    private static FakePlayer player(GameTestHelper h,BlockPos p){var actor=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"Hardening06"));actor.setPos(Vec3.atCenterOf(h.absolutePos(p)).add(0,1,1));return actor;}
    private static EnchantingTableBlockEntity rig(GameTestHelper h){h.setBlock(T,Blocks.ENCHANTING_TABLE);h.setBlock(P,InscribedRegistries.PEDESTAL.get());h.setBlock(S,Blocks.CHISELED_BOOKSHELF);var table=(EnchantingTableBlockEntity)h.getBlockEntity(T);AltarStateService.target(table,new ItemStack(Items.IRON_SWORD));((PedestalBlockEntity)h.getBlockEntity(P)).setItem(new ItemStack(Items.BLAZE_ROD));var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(enchant(h,"minecraft:sharpness"),3);book.enchant(enchant(h,"minecraft:unbreaking"),2);((ChiseledBookShelfBlockEntity)h.getBlockEntity(S)).setItem(0,book);return table;}
    @GameTest(template="test_altar") public static void playerDepartureCancelsWithoutTouchingInputs(GameTestHelper h){var table=rig(h);var actor=player(h,T);h.assertTrue(RitualController.startSelected(h.getLevel(),table.getBlockPos(),actor.getUUID(),id("inscribed:qa06_session"),RitualType.INFUSION).started(),"QA infusion unavailable");NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.entity.EntityLeaveLevelEvent(actor,h.getLevel()));h.assertTrue(RitualController.state(h.getLevel(),table.getBlockPos())==RitualState.IDLE&&!AltarStateService.get(table).running()&&((PedestalBlockEntity)h.getBlockEntity(P)).item().getCount()==1,"Departure consumed input or left zombie ritual");h.succeed();}
    @GameTest(template="test_altar") public static void directVanillaMenuCannotSpendLapisOrXp(GameTestHelper h){rig(h);var actor=player(h,T);actor.experienceLevel=30;var menu=new EnchantmentMenu(1,actor.getInventory(),ContainerLevelAccess.create(h.getLevel(),h.absolutePos(T)));var sword=new ItemStack(Items.DIAMOND_SWORD);menu.getSlot(0).set(sword.copy());menu.getSlot(1).set(new ItemStack(Items.LAPIS_LAZULI,64));menu.costs[0]=1;h.assertTrue(!menu.clickMenuButton(actor,0)&&actor.experienceLevel==30&&menu.getSlot(1).getItem().getCount()==64&&ItemStack.matches(menu.getSlot(0).getItem(),sword),"Direct random enchanting bypassed altar");h.succeed();}
    @GameTest(template="test_altar") public static void remoteAndSpectatorInteractionsDoNotTransfer(GameTestHelper h){rig(h);var p=(PedestalBlockEntity)h.getBlockEntity(P);p.setItem(ItemStack.EMPTY);var actor=player(h,T);actor.setPos(Vec3.atCenterOf(h.absolutePos(T)).add(100,0,0));actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND,64));h.assertTrue(!InfusionPedestalBlock.interact(h.getLevel(),p.getBlockPos(),actor,InteractionHand.MAIN_HAND)&&p.item().isEmpty()&&actor.getMainHandItem().getCount()==64,"Remote pedestal transfer succeeded");var event=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(actor,InteractionHand.MAIN_HAND,h.absolutePos(T),new BlockHitResult(Vec3.atCenterOf(h.absolutePos(T)),Direction.UP,h.absolutePos(T),false));NeoForge.EVENT_BUS.post(event);h.assertTrue(actor.getMainHandItem().getCount()==64,"Remote altar transfer succeeded");actor.setPos(Vec3.atCenterOf(h.absolutePos(P)));actor.setGameMode(net.minecraft.world.level.GameType.SPECTATOR);h.assertTrue(!InfusionPedestalBlock.interact(h.getLevel(),p.getBlockPos(),actor,InteractionHand.MAIN_HAND),"Spectator transfer succeeded");h.succeed();}
    @GameTest(template="test_altar") public static void spammedTransfersConserveSurvivalAndCreativeStacks(GameTestHelper h){rig(h);var p=(PedestalBlockEntity)h.getBlockEntity(P);for(var mode:List.of(net.minecraft.world.level.GameType.SURVIVAL,net.minecraft.world.level.GameType.CREATIVE)){p.setItem(ItemStack.EMPTY);var actor=player(h,P);actor.setGameMode(mode);var original=new ItemStack(Items.DIAMOND,64);actor.setItemInHand(InteractionHand.MAIN_HAND,original);for(int n=0;n<100;n++)InfusionPedestalBlock.interact(h.getLevel(),p.getBlockPos(),actor,InteractionHand.MAIN_HAND);h.assertTrue(p.item().getCount()==1&&original.getCount()==63,"Spam changed conservation in "+mode);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);for(int n=0;n<100;n++)InfusionPedestalBlock.interact(h.getLevel(),p.getBlockPos(),actor,InteractionHand.MAIN_HAND);h.assertTrue(p.item().getCount()+actor.getInventory().countItem(Items.DIAMOND)==1&&original.getCount()==63,"Retrieval duplicated stack in "+mode);}h.succeed();}
    @GameTest(template="test_altar") public static void pedestalMobilityAndAutomationFailClosed(GameTestHelper h)throws Exception{rig(h);var p=(PedestalBlockEntity)h.getBlockEntity(P);var state=p.getBlockState();h.assertTrue(!net.minecraft.world.level.block.piston.PistonBaseBlock.isPushable(state,h.getLevel(),p.getBlockPos(),Direction.EAST,true,Direction.EAST),"Piston can move pedestal");h.assertTrue(h.getLevel().getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,p.getBlockPos(),Direction.UP)==null,"Pedestal exposes unsupported automation");if(ModList.get().isLoaded("create")){var method=Class.forName("com.simibubi.create.api.contraption.BlockMovementChecks").getMethod("isMovementAllowed",net.minecraft.world.level.block.state.BlockState.class,net.minecraft.world.level.Level.class,BlockPos.class);h.assertTrue(Boolean.FALSE.equals(method.invoke(null,state,h.getLevel(),p.getBlockPos())),"Create can move stateful pedestal");}h.succeed();}
    @GameTest(template="test_altar",timeoutTicks=70) public static void multiEnchantmentBookRemainsIntactAndOutputUsesRecipeLevel(GameTestHelper h){var table=rig(h);var actor=player(h,T);var shelf=(ChiseledBookShelfBlockEntity)h.getBlockEntity(S);var original=shelf.getItem(0).copy();for(int i=0;i<20;i++){var match=dev.inscribed.recipe.RitualMatcher.matches(h.getLevel(),AltarScanner.scan(h.getLevel(),table.getBlockPos())).stream().filter(m->m.recipe().id().equals(id("inscribed:qa06_session"))).findFirst().orElseThrow();h.assertTrue(match.book().slot()==0,"Book selection was not deterministic");}h.assertTrue(RitualController.startSelected(h.getLevel(),table.getBlockPos(),actor.getUUID(),id("inscribed:qa06_session"),RitualType.INFUSION).started(),"QA infusion missing");h.runAtTickTime(50,()->{var target=AltarStateService.get(table).target();h.assertTrue(ItemStack.matches(original,shelf.getItem(0))&&EnchantmentHelper.getEnchantmentsForCrafting(target).getLevel(enchant(h,"minecraft:sharpness"))==1&&EnchantmentHelper.getEnchantmentsForCrafting(target).getLevel(enchant(h,"minecraft:unbreaking"))==0,"Multi-book was downgraded, consumed or applied unselected enchantment");h.succeed();});}
    @GameTest(template="test_altar",timeoutTicks=70) public static void extractionPreservesCustomDataAndAllOtherComponents(GameTestHelper h){var table=rig(h);var actor=player(h,T);var target=AltarStateService.get(table).target();target.enchant(enchant(h,"minecraft:sharpness"),1);target.enchant(enchant(h,"minecraft:unbreaking"),2);var nbt=new net.minecraft.nbt.CompoundTag();nbt.putString("othermod:custom_marker","preserve");target.set(DataComponents.CUSTOM_DATA,CustomData.of(nbt));target.set(DataComponents.CUSTOM_MODEL_DATA,new net.minecraft.world.item.component.CustomModelData(321));target.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("S?o Jo?o's blade / QA"));target.setDamageValue(17);AltarStateService.target(table,target);var expected=target.copy();EnchantmentHelper.updateEnchantments(expected,e->e.removeIf(enchant(h,"minecraft:sharpness")::equals));var shelf=(ChiseledBookShelfBlockEntity)h.getBlockEntity(S);shelf.setItem(0,new ItemStack(Items.BOOK));shelf.setItem(1,new ItemStack(Items.BOOK));h.assertTrue(RitualController.startSelected(h.getLevel(),table.getBlockPos(),actor.getUUID(),id("inscribed:qa06_session"),RitualType.EXTRACTION).started(),"QA extraction missing");h.runAtTickTime(50,()->{h.assertTrue(ItemStack.matches(expected,AltarStateService.get(table).target())&&shelf.getItem(0).is(Items.ENCHANTED_BOOK)&&shelf.getItem(1).is(Items.BOOK),"Extraction lost components or chose wrong output slot");h.succeed();});}
    @GameTest(template="test_altar") public static void disabledDatapackRecipeAndMissingTranslationAreSafe(GameTestHelper h){h.assertTrue(dev.inscribed.recipe.InscribedRecipeRegistry.recipes().stream().noneMatch(r->r.id().equals(id("inscribed:qa06_disabled"))),"Disabled datapack recipe registered");var name=dev.inscribed.knowledge.EnchantmentNames.component(enchant(h,"inscribed:qa_missing"));h.assertTrue(((net.minecraft.network.chat.contents.TranslatableContents)name.getContents()).getFallback().equals("Qa Missing"),"Missing translation produced raw key");h.succeed();}
    @GameTest(template="test_altar") public static void lootMissingChanceHasAuthorFacingError(GameTestHelper h){var doc=com.google.gson.JsonParser.parseString("{\"loot_tables\":[\"minecraft:chests/shipwreck_treasure\"],\"min_rolls\":1,\"max_rolls\":1,\"entries\":[{\"item\":\"minecraft:diamond\",\"weight\":1}]}").getAsJsonObject();boolean rejected=false;try{dev.inscribed.loot.LootInjection.parse(id("test:missing_chance"),doc,h.getLevel().registryAccess());}catch(IllegalArgumentException e){rejected=e.getMessage().contains("chance");}h.assertTrue(rejected,"Loot error omitted missing field");h.succeed();}
    @GameTest(template="test_altar") public static void legacyRuntimeTagsCannotResumeZombieAnimation(GameTestHelper h){rig(h);var p=(PedestalBlockEntity)h.getBlockEntity(P);var tag=p.saveWithFullMetadata(h.getLevel().registryAccess());tag.putBoolean("Running",true);tag.putLong("VisualStart",h.getLevel().getGameTime());tag.putInt("VisualDuration",1000);p.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(!p.running()&&p.visualStrength(h.getLevel().getGameTime())==0&&p.item().is(Items.BLAZE_ROD),"Old saved runtime tags resumed animation or lost storage");h.succeed();}
    private static final class OnceFailingShelf extends ChiseledBookShelfBlockEntity {
        boolean armed;
        OnceFailingShelf(BlockPos pos,net.minecraft.world.level.block.state.BlockState state){super(pos,state);}
        @Override public void setItem(int slot,ItemStack stack){if(armed){armed=false;throw new IllegalStateException("QA one-shot inventory failure");}super.setItem(slot,stack);}
    }
    @GameTest(template="test_altar",timeoutTicks=70) public static void inventoryFailureRollsBackEveryPhysicalInput(GameTestHelper h){
        var table=rig(h);var actor=player(h,T);var target=AltarStateService.get(table).target();target.enchant(enchant(h,"minecraft:sharpness"),1);AltarStateService.target(table,target);
        var pos=h.absolutePos(S);var shelf=new OnceFailingShelf(pos,h.getLevel().getBlockState(pos));h.getLevel().setBlockEntity(shelf);shelf.setItem(0,new ItemStack(Items.BOOK));
        h.assertTrue(RitualController.startSelected(h.getLevel(),table.getBlockPos(),actor.getUUID(),id("inscribed:qa06_session"),RitualType.EXTRACTION).started(),"Failure fixture unavailable");shelf.armed=true;
        h.runAtTickTime(50,()->{h.assertTrue(ItemStack.matches(target,AltarStateService.get(table).target())&&((PedestalBlockEntity)h.getBlockEntity(P)).item().is(Items.BLAZE_ROD)&&shelf.getItem(0).is(Items.BOOK)&&!AltarStateService.get(table).running(),"Rollback lost, duplicated or partially committed inputs");h.succeed();});
    }

    @GameTest(template="test_altar") public static void exportedConfigurationInventoryHasValidLiveDefaults(GameTestHelper h)throws Exception{
        var inventory=new TreeMap<String,Object>();for(var field:dev.inscribed.config.InscribedConfig.class.getFields())if(field.get(null) instanceof net.neoforged.neoforge.common.ModConfigSpec.ConfigValue<?> value){var spec=value.getSpec();var row=new LinkedHashMap<String,Object>();row.put("field",field.getName());row.put("default",value.getDefault());row.put("type",value.getDefault().getClass().getSimpleName());row.put("scope","SERVER");row.put("purpose",spec.getComment());row.put("deprecated",false);row.put("used",true);inventory.put(String.join(".",value.getPath()),row);}
        h.assertTrue(inventory.size()>=50,"Config inventory incomplete");java.nio.file.Files.writeString(java.nio.file.Path.of("config-inventory.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(inventory));h.succeed();
    }

}
